		function setStop(evt)
                {   		    
                    object = svgRoot.getElementById("emergencycar");
                    object.setAttribute("points","0,0");                   	    
                    startx = endx;
                    starty = endy;
                }

                function move( x_pos, y_pos )
                {                    
                    //trueCoordinate(evt);
		    //objectCoor = GetTrueCoords( evt.getClientX(), evt.getClientY() );
                    //endx = objectCoor.x;
                    //endy = objectCoor.y;
		    endx = x_pos+350;
                    endy = (y_pos*(-1))+250.5;
                    object = svgRoot.getElementById("emergencycar");		    
                    difx = endx - 0;
                    dify = endy - 0;		    
                    animate = svgRoot.getElementById("caranimate");
                    animate.endElement();
                    animate.setAttribute( "from", startx + "," + starty);
                    animate.setAttribute( "to", difx + "," + dify );
                    animate.beginElement();

		    idifx = endx - startx;//Math.abs(endx - startx);
		    idify = endy - starty;//Math.abs(endy - starty); 

		    newangle = 180*(1/(Math.PI/Math.atan2(idify,idifx)));
		    if( oldangle >= 0 )
		    {
			if( newangle < oldangle && newangle >= ((180-oldangle)*(-1)))
			{			    
			    toturnangle = newangle;
			}
			else
			{
			    if( newangle < 0 && newangle < (-(180-oldangle)))
			    {
				toturnangle = 180 + ( 180 + newangle );
			    }
			    else
			    {
				toturnangle = newangle;
			    }
			}
	            }
		    else if( oldangle < 0 )
		    {
			if( newangle > oldangle && newangle <= ((180+oldangle)))
			{			    			    		    
			    toturnangle = newangle;
			}
			else
			{
			    if(newangle > 0 && newangle > (180 + oldangle))
			    {
				toturnangle = -180-(180-newangle);
			    }
			    else
			    {
				toturnangle = newangle;
			    }			    		   
			}
	            }
		    animate1 = svgRoot.getElementById(anid);
		    animate1.endElement();
		    animate1.setAttribute( "from", oldangle );
		    animate1.setAttribute( "to", toturnangle );
	            animate1.beginElement();
		    oldangle = newangle;			    		    
                }


                function trueCoordinate(evt)
                {                   
                    svgDocument = evt.getTarget().getOwnerDocument();
                    svgRoot = svgDocument.documentElement;	
                    objectScale = 1/svgRoot.currentScale;
                    objectTranslation = svgRoot.currentTranslate;

                    viewBoxes = svgRoot.getAttribute( "viewBox" );
                    posi = viewBoxes.indexOf(" ");
                    posi2 = posi+1;
                    view_x = viewBoxes.substring( 0, posi );
                    view_x_int = parseFloat(view_x);
                    posi = viewBoxes.indexOf(" ", posi2);
                    view_y = viewBoxes.substring( posi2, posi );
                    view_y_int = parseFloat(view_y);

                    objectCoor.x = view_x_int+(evt.getClientX() - objectTranslation.x)*defiScale/objectScale;
                    objectCoor.y = view_y_int+(evt.getClientY() - objectTranslation.y)*defiScale/objectScale;                    
                };
