                function GetTrueCoords( evt_x, evt_y )
                {                    
                    //svgDocument = evt.getTarget().getOwnerDocument();
                    svgRoot = svgDocument.documentElement;	
                    newScale = svgRoot.currentScale;
                    translation = svgRoot.currentTranslate;

                    viewBoxes = svgRoot.getAttribute( "viewBox" );
                    posi = viewBoxes.indexOf(" ");
                    posi2 = posi+1;
                    view_x = viewBoxes.substring( 0, posi );
                    view_x_int = parseFloat(view_x);
                    posi = viewBoxes.indexOf(" ", posi2);
                    view_y = viewBoxes.substring( posi2, posi );
                    view_y_int = parseFloat(view_y);

                    returnTrueCoords.x = view_x_int+(evt_x - translation.x)*defiScale/newScale;
                    returnTrueCoords.y = view_y_int+(evt_y - translation.y)*defiScale/newScale;

		    return returnTrueCoords;

                };
                function hideTooltip(evt)
                {
                    tooltip.setAttributeNS(null, 'visibility', 'hidden');
		    tipBox.setAttributeNS(null, 'visibility', 'hidden');
                }
                function position(evt,txtDesc)
                {                   
                    TrueCoords = GetTrueCoords( evt.getClientX(), evt.getClientY() );
		    tipScale = 1/svgRoot.currentScale;
		    tipBox.setAttributeNS(null, 'transform', 'scale(' + tipScale + ',' + tipScale + ')' );
		    tipText.setAttributeNS(null, 'transform', 'scale(' + tipScale + ',' + tipScale + ')' );

		    tipText.firstChild.setData(txtDesc);

		    xPos=TrueCoords.x+(450*tipScale);
		    yPos=TrueCoords.y+(450*tipScale);
		    /////Add new/////
                    outLine = tipText.getBBox();		
                    tipBox.setAttribute('width',Number(outLine.width)+900);
                    tipBox.setAttribute('height',Number(outLine.height)+600);		
                    tipBox.setAttribute('visibility', 'visible');
		    tooltip.setAttribute('visibility', 'visible');
		    tooltip.setAttributeNS(null, 'transform', 'translate(' + xPos + ',' + yPos + ')');
		}
