		function zoomtofit(round)
		{
		    svgRoot.currentScale = 0.5;
		    svgRoot.currentTranslate.x = 0;
		    svgRoot.currentTranslate.y = 0;
		    //setTimeout('svgRoot.currentTranslate.y = 0',75);
		    //svgRoot.currentScale = 0.0625;
		    if (round == 1)
		    {
			setTimeout('zoomtofit(0)',75);
		    }		    
		}

		function moveleft()
		{
		    svgRoot.currentTranslate.x = svgRoot.currentTranslate.x + 10;
		}

		function moveright()
		{
		    svgRoot.currentTranslate.x = svgRoot.currentTranslate.x - 10;
		}

		function moveup()
		{
		    svgRoot.currentTranslate.y = svgRoot.currentTranslate.y + 10;
		}

		function movedown()
		{
		    svgRoot.currentTranslate.y = svgRoot.currentTranslate.y - 10;
		}

		function zoomout()
		{		    		    
		    zoombar( svgRoot.currentScale / 2 * 1000)
		}
		function zoomin()
		{
		    zoombar( svgRoot.currentScale * 2 * 1000 )		    	    
		}
		function WorldToScreen( wx_utm, wy_utm )
		{
		    //svgDocument = evt.getTarget().getOwnerDocument();
		    //alert('A KMITL '+wx_utm+',,'+wy_utm);
                    svgRoot = svgDocument.documentElement;	
                    newScale = svgRoot.currentScale;
                    translation = svgRoot.currentTranslate;

		    //alert('scale = '+svgRoot.currentScale+':::t = '+svgRoot.currentTranslate.x+','+svgRoot.currentTranslate.y);

                    viewBoxes = svgRoot.getAttribute( "viewBox" );
                    posi = viewBoxes.indexOf(" ");
                    posi2 = posi+1;
                    view_x = viewBoxes.substring( 0, posi );
                    view_x_int = parseFloat(view_x);
                    posi = viewBoxes.indexOf(" ", posi2);
                    view_y = viewBoxes.substring( posi2, posi );
                    view_y_int = parseFloat(view_y);

                    //returnTrueCoords.x = view_x_int+(evt_x - translation.x)*defiScale/newScale;
                    //returnTrueCoords.y = view_y_int+(evt_y - translation.y)*defiScale/newScale;
		    picposition_x = translation.x - ((( view_x_int - wx_utm )*newScale)/defiScale);
		    picposition_y = translation.y - ((( view_y_int - wy_utm )*newScale)/defiScale);
		    pp = svgRoot.createSVGPoint();
		    pp.x = picposition_x;
		    pp.y = picposition_y;

		    return pp;
		}

		function MoveToCenter( x, y )
		{
		    pp = WorldToScreen( x, y );//692185, -1518531 );//coor.x, coor.y );
		    //alert('xx = '+pp.x+'::: yy ='+pp.y);
		    svgRoot.currentTranslate.x = svgRoot.currentTranslate.x + ( 332.5 - pp.x );
		    svgRoot.currentTranslate.y = svgRoot.currentTranslate.y + ( 240 - pp.y );
		    //alert('xx = '+pp.x+'::: yy ='+pp.y);
		    //setTimeout('MoveToCenter( x, y )',1000);
		    //setTimeout('svgRoot.currentTranslate.y = svgRoot.currentTranslate.y + ( 240 - pp.y )',75);
		}
		function status_zoom_bar( id_object )
		{
		    oldBar.setAttributeNS(null, 'fill', 'white');
		    oldBar = svgRoot.getElementById( id_object );
		    oldBar.setAttributeNS(null, 'fill', 'red');
		}
		function zoombar( value )
		{
		    popupTrueCoor1 = GetTrueCoords( 332.5, 240 );
		    //alert(popupTrueCoor1.x+",,,,"+popupTrueCoor1.y);
		    ppx = popupTrueCoor1.x;
		    ppy = popupTrueCoor1.y;

		    if( value == 8 || value == 16000 )
		    {
			svgRoot.currentScale = 16;			
			status_zoom_bar( "barscale8" );
		    }
		    else if( value == 7 || value == 8000 )
		    {
			svgRoot.currentScale = 8;
			status_zoom_bar( "barscale7" );
		    }
		    else if( value == 6 || value == 4000 )
		    {
			svgRoot.currentScale = 4;
			status_zoom_bar( "barscale6" );
		    }
		    else if( value == 5 || value == 2000 )
		    {
			svgRoot.currentScale = 2;
			status_zoom_bar( "barscale5" );
		    }
		    else if( value == 4 || value == 1000 )
		    {
			svgRoot.currentScale = 1;
			status_zoom_bar( "barscale4" );
		    }
		    else if( value == 3 || value == 500 )
		    {
			svgRoot.currentScale = 0.5;
			status_zoom_bar( "barscale3" );
		    }
		    else if( value == 2 || value == 250 )
		    {
			svgRoot.currentScale = 0.25;
			status_zoom_bar( "barscale2" );
		    }
		    else if( value == 1 || value == 125 )
		    {
			svgRoot.currentScale = 0.125;
			status_zoom_bar( "barscale1" );
		    }
		    else if( value == 0 || value == 62.5 )
		    {
			svgRoot.currentScale = 0.0625;
			status_zoom_bar( "barscale0" );
		    }		    
		    //setTimeout('MoveToCenter(ppx, ppy)',500);
		    if((value < 9 && value >= 0)||(value < 17000 && value >= 62.5))
		    {MoveToCenter(ppx, ppy);		    }
		    /*pp = WorldToScreen( ppx, ppy );//692185, -1518531 );//coor.x, coor.y );
		    //alert('xx = '+pp.x+'::: yy ='+pp.y);
		    //setTimeout('svgRoot.currentTranslate.x = svgRoot.currentTranslate.x + ( 332.5 - pp.x );svgRoot.currentTranslate.y = svgRoot.currentTranslate.y + ( 240 - pp.y );',250);
		    svgRoot.currentTranslate.x = svgRoot.currentTranslate.x + ( 332.5 - pp.x );
		    svgRoot.currentTranslate.y = svgRoot.currentTranslate.y + ( 240 - pp.y );*/
		}
		function GetXmlHttpObject()
		{ 
			var objXMLHttp=null;
			if (window.XMLHttpRequest)
			{
				objXMLHttp=new XMLHttpRequest();
			}
			else if (window.ActiveXObject)
			{
				objXMLHttp=new ActiveXObject("Microsoft.XMLHTTP");
			}
			return objXMLHttp;
		} 
		var xmlHttpRequest = null;

		function onRequest(type)
		{        		   		    								
		    xmlHttpRequest=GetXmlHttpObject();
		    if (xmlHttpRequest==null)
		    {
			alert ("Browser does not support HTTP Request");
			return;
		    }

		    if (type == '00000001' )
		    {
			anid = "direction1"
			object = svgRoot.getElementById("emergencycar");
			object.setAttributeNS(null, 'marker-end', 'url(#memercar)' );
		    }
		    else if (type == '00000002' )
		    {
			anid = "direction2"
			object = svgRoot.getElementById("emergencycar");
			object.setAttributeNS(null, 'marker-end', 'url(#policecar)' );
		    }
		    else if (type == '00000003' )
		    {
			anid = "direction3"
			object = svgRoot.getElementById("emergencycar");
			object.setAttributeNS(null, 'marker-end', 'url(#firecar)' );
		    }

		    var url="./xml/serv.py/requests?type="+type+"&x_pos="+String(req_x)+"&y_pos="+String(req_y);	
		    xmlHttpRequest.onreadystatechange=stateChangedRequest;
		    xmlHttpRequest.open("GET",url,true);
		    xmlHttpRequest.send(null);			    							
                }

	        function stateChangedRequest() 
		{ 
		    if (xmlHttpRequest.readyState==4 || xmlHttpRequest.readyState=="complete")
	            { 					
		        docxml = xmlHttpRequest.responseXML;					
		        dataRoot = docxml.documentElement;
			//subr = dataRoot.getElementsByTagName("service");
		        //alert(dataRoot.getAttribute("servid"));
			servID = dataRoot.getAttribute("servid");
			if ( servID == 'None' )
			{
			   alert( "None Service!!" );
			 }
			 else
			 {  
			    alert( "Requested !!" );
			    onTrack();
			  }
		    } 
		}
		var xmlHttpTrack = null;
		function onTrack()
		{   
		    xmlHttpTrack = null;
		    xmlHttpTrack = GetXmlHttpObject();
		    if ( xmlHttpTrack == null )
		    {
			alert ("Browser does not support HTTP Request");
			return;
		    } 
		    var url="./../xml/serv.py/ontrack?serv_id="+servID;	
		    xmlHttpTrack.onreadystatechange = stateChangedTrack;
		    xmlHttpTrack.open( "POST", url, true );
		    xmlHttpTrack.send( null );			    							
                }

	        function stateChangedTrack() 
		{ 
		    if ( xmlHttpTrack.readyState == 4 || xmlHttpTrack.readyState == "complete" )
	            { 					
		        docxml = xmlHttpTrack.responseXML;					
		        dataRoot = docxml.documentElement;
			subr = dataRoot.getElementsByTagName("car");
		        //alert(subr[0].getAttribute("xpos"));
			//alert(subr[0].getAttribute("ypos"));
			move( parseFloat(subr[0].getAttribute("xpos")), parseFloat(subr[0].getAttribute("ypos")));

			//alert(servID);
			//alert(subr[0].getAttribute("state"));
			if ( subr[0].getAttribute("state") == '00' )
			{
			   setTimeout("onTrack()",1000);
			}
			else
			{
			   alert(" Complete -- Thank you -- ");
			}
		    } 
		}
